const cashPoint=e=>{const r=cashCanvas.getBoundingClientRect();return {x:(e.clientX-r.left)*cashCanvas.width/r.width,y:(e.clientY-r.top)*cashCanvas.height/r.height};};
cashCanvas.onpointerdown=e=>{if(cashSaving||cashAttempt)return;cashWriting=true;cashCanvas.setPointerCapture(e.pointerId);const p=cashPoint(e);cashContext.beginPath();cashContext.moveTo(p.x,p.y);cashContext.lineWidth=3;cashContext.lineCap='round';cashContext.strokeStyle='#203b2a';};cashCanvas.onpointermove=e=>{if(cashWriting){const p=cashPoint(e);cashContext.lineTo(p.x,p.y);cashContext.stroke();cashInk=true;}};cashCanvas.onpointerup=()=>cashWriting=false;cashCanvas.onpointercancel=()=>cashWriting=false;
