$('saveCashSettlement').onclick=async()=>{if(cashSaving||!cashSigning||!current||!online())return;const uid=current.uid,e=epoch,signerName=$('cashSignerName').value.trim();if(!cashAttempt&&(!cashInk||signerName.length<2)){return $('cashSettlementStatus').textContent='Bitte Namen eintragen und unterschreiben.';}cashSaving=true;for(const id of ['saveCashSettlement','cancelCashSettlement','clearCashSignature','cashSignerName'])$(id).disabled=true;try{if(!cashAttempt){let key=await getPublicKey(uid);if(!key){key=await call('getDeliveryEncryptionKey');await savePublicKey(uid,key);}const completionId=crypto.randomUUID(),capturedAt=new Date().toISOString();if(!key)throw Error('Tour im WLAN neu laden.');cashAttempt={...cashSigning,signerName,completionId,capturedAt,sealedSignature:await sealSignature(key,{uid,tourId:cashSigning.tourId,purpose:'marien-cash-settlement',completionId},cashCanvas.toDataURL('image/png'),capturedAt)};}await call('saveCashSettlement',cashAttempt);if(e!==epoch||uid!==current?.uid)return;await loadState();cashSaving=false;closeCashSettlement();info('Marienapotheken-Abrechnung mit Unterschrift gespeichert.');}catch(error){$('cashSettlementStatus').textContent='Speicherung nicht bestätigt: '+error.message+' Bitte Fenster offen lassen und erneut speichern; dieselbe Unterschrift wird nur einmal archiviert.';}finally{cashSaving=false;for(const id of ['saveCashSettlement','cancelCashSettlement','clearCashSignature','cashSignerName'])$(id).disabled=cashAttempt&&['cashSignerName','clearCashSignature'].includes(id);}}
async function viewCashSignature(tourId){if(!has('office')||!online())return;const uid=current?.uid,e=epoch;try{const {proof}=await call('downloadCashSettlement',{tourId});if(e!==epoch||uid!==current?.uid||!has('office'))return;if(!/^data:image\/png;base64,[A-Za-z0-9+/]+={0,2}$/.test(proof.signature))throw Error('Unterschrift kann nicht angezeigt werden.');const dialog=document.createElement('dialog'),heading=document.createElement('h2'),details=document.createElement('p'),image=document.createElement('img'),close=document.createElement('button');heading.textContent='Abrechnungsunterschrift';details.textContent=proof.signerName+' · '+localTimestamp(proof.completedAt);image.src=proof.signature;image.alt='Unterschrift der abrechnenden Person';image.style.maxWidth='100%';close.textContent='Schließen';close.onclick=()=>dialog.close();dialog.append(heading,details,image,close);document.body.append(dialog);const clear=()=>dialog.close();document.addEventListener('marapo24-clear-sensitive',clear,{once:true});dialog.addEventListener('close',()=>{document.removeEventListener('marapo24-clear-sensitive',clear);image.removeAttribute('src');dialog.remove();},{once:true});dialog.showModal();}catch(error){info(error.message);}}
